def semver_sort(versions):
    def parse_version(version):
        # Split by '+' to remove build metadata
        version_without_build = version.split('+')[0]

        # Split by '-' to separate base version from pre-release
        if '-' in version_without_build:
            base, prerelease = version_without_build.split('-', 1)
        else:
            base = version_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if identifier is all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        index, version = item
        major, minor, patch, prerelease_ids = parse_version(version)

        # Return tuple for sorting:
        # - major, minor, patch (numeric)
        # - has_prerelease (False = no prerelease, True = has prerelease) - inverted so no prerelease sorts after
        # - prerelease_identifiers (tuple of tuples for comparison)
        # - original index (to maintain input order for equal precedence)
        return (major, minor, patch, len(prerelease_ids) > 0, prerelease_ids, index)

    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=compare_key)
    return [v for i, v in sorted_versions]

